# %% ../nbs/03_calculate_csp.ipynb 3
import numpy as np
from functools import lru_cache
from .ssp_interpolation import spec_ssp_lookup, spec_ssp_lookup_many, ssp_weight_grid, smooth_particle_sfh

from .load_sps_library import load_fsps_spectral_library, load_fsps_age_metallicity
