# %% ../nbs/03_calculate_csp.ipynb 5
def total_luminosity(spec_flux_ssp:np.ndarray, # SSP SEDs   
                     spec_wave:np.array # SED Wavelength
                    )-> np.float32: #Luminosity
    flux_proxy = np.trapezoid(spec_flux_ssp, spec_wave, axis=1) 
    return flux_proxy


def galaxy_stellar_mass(selected_star_masses:np.array #SSP masses in a galaxy
                       )-> np.float32: # Total stellar mass of the galaxy
    
    gal_stellar_mass = np.sum(selected_star_masses)
    return gal_stellar_mass


def ssp_to_csp(spec_flux_ssp:np.ndarray # SSP SEDs
              )-> np.array: #CSP SED
    spec_csp = np.sum(spec_flux_ssp, axis=0) ## CSP
    return spec_csp

# %% ../nbs/03_calculate_csp.ipynb 6
BIRTH_CLOUD_AGE_GYR = 0.01 # Stars younger than this (10 Myr) are still in their birth clouds (Charlot & Fall 2000)


@lru_cache(maxsize=4)
def _load_library_cached(spectral_library_flux, spectral_library_wave, spectral_library_age, spectral_library_metal):
    # The library is ~32 MB and was being re-read for every galaxy; treat the cached arrays as read-only.
    spec_flux_library, spec_wave_library = load_fsps_spectral_library(spectral_library_flux, spectral_library_wave)
    age_fsps_gyr, Z_padova_fsps = load_fsps_age_metallicity(spectral_library_age, spectral_library_metal)
    return spec_flux_library, spec_wave_library, age_fsps_gyr, Z_padova_fsps


def calc_fluxes_for_individual_galaxy(galaxy_tags_hacc:np.array=None, # HACC galaxy tags,
                                      metal_hacc:np.array=None, # Metallicity in the HACC catalog,
                                      mass_hacc:np.array=None, # Mass in the HACC catalog,
                                      age_hacc:np.array=None, # Age in the HACC catalog,
                                      unique_gal_tag:np.float32=None, # Selected galaxy tag
                                      spectral_library_flux:str=LIBRARY_FLUX_FILE, # Fluxes in the spectral library,
                                      spectral_library_wave:str=LIBRARY_WAVE_FILE, # Wavelengths in the spectral library,
                                      spectral_library_age:str=LIBRARY_AGE_FILE, # Age in the spectral library,
                                      spectral_library_metal:str=LIBRARY_METAL_FILE, # Metallicity in the spectral library,
                                      mass_formed_hacc:np.array=None, # Initial (formed) particle masses; SSP weights. Falls back to `mass_hacc`
                                      return_ssp_spectra:bool=True, # Build the per-particle SSP SEDs (memory ~ n_particles x n_wave); if False only the CSP is computed
                                      smooth_sfh:bool=True, # Spread each particle over the age interval it samples (see `smooth_particle_sfh`) instead of a delta burst
                                      n_sub:int=16, # Sub-particles per particle when `smooth_sfh`
                                      return_young_csp:bool=False, # Append the CSP of stars younger than `young_age_gyr` as a 6th entry (for birth-cloud dust)
                                      young_age_gyr:np.float32=BIRTH_CLOUD_AGE_GYR, # Age limit of the young component (Gyr)
                                      )->tuple: # SED wavelength (A), individual SSP SEDs (Lsun/A), CSP SED (Lsun/A), Luminosity, Galaxy stellar mass (Msun)
    '''
    SSP library is per unit mass *formed*: pass the particles' initial masses
    as `mass_formed_hacc` for the SED weights. `mass_hacc` (current mass) is
    still what the returned galaxy stellar mass is made of.
    '''
    spec_flux_library, spec_wave_library, age_fsps_gyr, Z_padova_fsps = _load_library_cached(
        spectral_library_flux, spectral_library_wave, spectral_library_age, spectral_library_metal)

    gal_tag_cond = np.where(galaxy_tags_hacc == unique_gal_tag)
    ssp_weights = mass_hacc if mass_formed_hacc is None else mass_formed_hacc

    # (n_particles, n_sub) ages; every sub-particle carries 1/n_sub of its particle's mass
    n_sub = n_sub if smooth_sfh else 1
    age_sub = smooth_particle_sfh(age_hacc[gal_tag_cond], n_sub=n_sub)
    metal_gal, weight_sub = metal_hacc[gal_tag_cond], ssp_weights[gal_tag_cond]/n_sub

    if return_ssp_spectra:
        spec_wave_ssp = spec_wave_library
        spec_flux_ssp = np.zeros(shape=(gal_tag_cond[0].shape[0], spec_wave_library.shape[0]))
        for k in range(n_sub): # one sub-sample at a time keeps the memory at n_particles x n_wave
            spec_flux_ssp += spec_ssp_lookup_many(age_sub[:, k], metal_gal, weight_sub,
                                                  age_fsps_gyr, Z_padova_fsps, spec_flux_library, spec_wave_library)[1]
        spec_csp = ssp_to_csp(spec_flux_ssp)
        flux_proxy = total_luminosity(spec_flux_ssp, spec_wave_library)
    else:
        # Deposit particles on the (Z, age) grid, then one contraction: cost independent of particle number
        weight_grid = ssp_weight_grid(age_sub.ravel(), np.repeat(metal_gal, n_sub), np.repeat(weight_sub, n_sub),
                                      age_fsps_gyr, Z_padova_fsps)
        spec_wave_ssp, spec_flux_ssp = spec_wave_library, None
        spec_csp = np.tensordot(weight_grid, spec_flux_library, axes=([0, 1], [0, 1]))
        flux_proxy = np.trapezoid(spec_csp, spec_wave_library)

    gal_stellar_mass = galaxy_stellar_mass(mass_hacc[gal_tag_cond])

    if return_young_csp:
        young = age_sub.ravel() < young_age_gyr
        young_grid = ssp_weight_grid(age_sub.ravel()[young], np.repeat(metal_gal, n_sub)[young], np.repeat(weight_sub, n_sub)[young],
                                     age_fsps_gyr, Z_padova_fsps)
        spec_csp_young = np.tensordot(young_grid, spec_flux_library, axes=([0, 1], [0, 1]))
        return spec_wave_ssp, spec_flux_ssp, spec_csp, flux_proxy, gal_stellar_mass, spec_csp_young

    return spec_wave_ssp, spec_flux_ssp, spec_csp, flux_proxy, gal_stellar_mass

# %% ../nbs/03_calculate_csp.ipynb 7
def calc_csp_for_galaxies(galaxy_tags_hacc:np.array=None, # HACC galaxy tags of the particles,
                          metal_hacc:np.array=None, # Particle metallicities (Z/Zsun),
                          mass_formed_hacc:np.array=None, # Particle initial (formed) masses (Msun),
                          age_hacc:np.array=None, # Particle ages (Gyr),
                          unique_gal_tags:np.array=None, # Galaxies to build; None -> all, in np.unique order
                          spectral_library_flux:str=LIBRARY_FLUX_FILE, # Fluxes in the spectral library,
                          spectral_library_wave:str=LIBRARY_WAVE_FILE, # Wavelengths in the spectral library,
                          spectral_library_age:str=LIBRARY_AGE_FILE, # Age in the spectral library,
                          spectral_library_metal:str=LIBRARY_METAL_FILE, # Metallicity in the spectral library,
                          smooth_sfh:bool=True, # Spread each particle over the age interval it samples
                          n_sub:int=16, # Sub-particles per particle when `smooth_sfh`
                          young_age_gyr:np.float32=BIRTH_CLOUD_AGE_GYR, # Age limit of the young (birth-cloud) component (Gyr)
                          )->tuple: # SED wavelength (A), CSP SEDs (Lsun/A) [n_gal, n_wave], CSPs of the young stars only [n_gal, n_wave]
    '''
    Rest-frame, dust-free CSPs of many galaxies at once. Every galaxy is
    reduced to its mass-formed weights on the (Z, age) library grid, and all
    SEDs then come out of one matrix product -- thousands of galaxies per
    second, independent of their particle numbers.
    '''
    spec_flux_library, spec_wave_library, age_fsps_gyr, Z_padova_fsps = _load_library_cached(
        spectral_library_flux, spectral_library_wave, spectral_library_age, spectral_library_metal)

    if unique_gal_tags is None:
        unique_gal_tags = np.unique(galaxy_tags_hacc)
    unique_gal_tags = np.atleast_1d(unique_gal_tags)

    order = np.argsort(galaxy_tags_hacc, kind='stable')
    tags_sorted = galaxy_tags_hacc[order]
    starts = np.searchsorted(tags_sorted, unique_gal_tags, side='left')
    ends = np.searchsorted(tags_sorted, unique_gal_tags, side='right')

    n_sub = n_sub if smooth_sfh else 1
    n_nodes = Z_padova_fsps.shape[0]*age_fsps_gyr.shape[0]
    weights_all = np.zeros((unique_gal_tags.shape[0], n_nodes))
    weights_young = np.zeros((unique_gal_tags.shape[0], n_nodes))

    for g, (start, end) in enumerate(zip(starts, ends)):
        if end == start:
            continue
        idx = order[start:end]
        age_sub = smooth_particle_sfh(age_hacc[idx], n_sub=n_sub).ravel()
        metal_sub = np.repeat(metal_hacc[idx], n_sub)
        weight_sub = np.repeat(mass_formed_hacc[idx]/n_sub, n_sub)
        weights_all[g] = ssp_weight_grid(age_sub, metal_sub, weight_sub, age_fsps_gyr, Z_padova_fsps).ravel()
        young = age_sub < young_age_gyr
        if young.any():
            weights_young[g] = ssp_weight_grid(age_sub[young], metal_sub[young], weight_sub[young], age_fsps_gyr, Z_padova_fsps).ravel()

    library_2d = spec_flux_library.reshape(n_nodes, -1)
    return spec_wave_library, weights_all @ library_2d, weights_young @ library_2d
